  "test_path": "tests/test_duckduckgo_tool.py",
  "test": "import types
import sys

import pytest


def test_duckduckgo_no_results_raises_valueerror(monkeypatch):
    # Create a dummy ddgs module with a DDGS class that returns empty results
    dummy_module = types.ModuleType("ddgs")

    class DummyDDGS:
        def __init__(self, **kwargs):
            pass

        def text(self, query, max_results):
            return []

    dummy_module.DDGS = DummyDDGS
    monkeypatch.setitem(sys.modules, "ddgs", dummy_module)

    from smolagents.default_tools import DuckDuckGoSearchTool

    tool = DuckDuckGoSearchTool()
    with pytest.raises(ValueError, match="No results found!"):
        tool.forward("test query")
